namespace Ordering;

/// <summary>
/// Drives an order from intake through tax to dispatch.
/// </summary>
public sealed class OrderProcessor
{
    private readonly OrderValidationComponent _validation;
    private readonly OrderTaxComponent _tax;
    private readonly OrderDispatchComponent _dispatch;
    private readonly OrderCommercialComponent _commercial;

    public OrderProcessor(IShipper shipper)
    {
        var blockedCountries = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "KP", "SY" };
        var ratesByCountry = new Dictionary<string, decimal>(StringComparer.OrdinalIgnoreCase)
        {
            ["GB"] = 0.20m,
            ["DE"] = 0.19m,
            ["FR"] = 0.20m,
            ["US"] = 0.00m,
        };

        _validation = new OrderValidationComponent(10m, blockedCountries);
        _tax = new OrderTaxComponent(ratesByCountry, 0.15m);
        _dispatch = new OrderDispatchComponent(shipper, blockedCountries);
        _commercial = new OrderCommercialComponent();
    }

    public IReadOnlyList<string> ValidateOrder(Order order, Customer customer) =>
        _validation.ValidateOrder(order, customer);

    public bool MeetsMinimum(Order order) => _validation.MeetsMinimum(order);

    public bool CheckAddress(Address address) => _validation.CheckAddress(address);

    public decimal ComputeTax(Order order, Customer customer) => _tax.ComputeTax(order, customer);

    public decimal ResolveRate(string countryCode) => _tax.ResolveRate(countryCode);

    public decimal ApplyRounding(decimal value) => _tax.ApplyRounding(value);

    public decimal EstimateDuty(Order order, Customer customer) => _tax.EstimateDuty(order, customer);

    public string Dispatch(Order order, Customer customer) => _dispatch.Dispatch(order, customer);

    public string SelectService(Customer customer) => _dispatch.SelectService(customer);

    public IReadOnlyList<string> BuildManifest(Order order) => _dispatch.BuildManifest(order);

    public string Classify(Order order, Customer customer) => _commercial.Classify(order, customer);

    public decimal ApplyDiscount(Order order, Customer customer) =>
        _commercial.ApplyDiscount(order, customer);

    public int DispatchedCount => _dispatch.DispatchedCount;
}

internal sealed class OrderValidationComponent
{
    private readonly decimal _minimumOrderValue;
    private readonly HashSet<string> _blockedCountries;

    internal OrderValidationComponent(decimal minimumOrderValue, HashSet<string> blockedCountries)
    {
        _minimumOrderValue = minimumOrderValue;
        _blockedCountries = blockedCountries;
    }

    internal IReadOnlyList<string> ValidateOrder(Order order, Customer customer)
    {
        var problems = new List<string>();
        if (customer.Tier == CustomerTier.Blocked)
            problems.Add("customer is blocked");
        if (order.Lines.Count == 0)
            problems.Add("order has no lines");

        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                problems.Add($"quantity invalid for {line.Sku}");
            if (line.UnitPrice < 0m)
                problems.Add($"price invalid for {line.Sku}");
            if (string.IsNullOrEmpty(line.Sku))
                problems.Add("line missing sku");
        }

        if (_blockedCountries.Contains(customer.Address.CountryCode))
            problems.Add("destination not served");
        if (customer.Tier != CustomerTier.Wholesale && !MeetsMinimum(order))
            problems.Add("below minimum order value");
        return problems;
    }

    internal bool MeetsMinimum(Order order)
    {
        decimal total = 0m;
        foreach (var line in order.Lines)
        {
            if (line.Quantity > 0)
                total += line.UnitPrice * line.Quantity;
        }
        return total >= _minimumOrderValue;
    }

    internal bool CheckAddress(Address address)
    {
        if (string.IsNullOrWhiteSpace(address.CountryCode))
            return false;
        if (string.IsNullOrWhiteSpace(address.City))
            return false;
        if (_blockedCountries.Contains(address.CountryCode))
            return false;
        if (address.CountryCode == "GB" && address.PostalCode.Length < 5)
            return false;
        return address.PostalCode.Length > 0 || address.City.Length > 3;
    }
}

internal sealed class OrderTaxComponent
{
    private readonly Dictionary<string, decimal> _ratesByCountry;
    private readonly decimal _fallbackRate;

    internal OrderTaxComponent(Dictionary<string, decimal> ratesByCountry, decimal fallbackRate)
    {
        _ratesByCountry = ratesByCountry;
        _fallbackRate = fallbackRate;
    }

    internal decimal ComputeTax(Order order, Customer customer)
    {
        var rate = ResolveRate(customer.Address.CountryCode);
        decimal tax = 0m;
        foreach (var line in order.Lines)
        {
            var net = line.UnitPrice * line.Quantity;
            switch (customer.Tier)
            {
                case CustomerTier.Wholesale:
                    tax += net * rate * 0.9m;
                    break;
                case CustomerTier.Standard:
                    tax += net * rate;
                    break;
                case CustomerTier.Blocked:
                    break;
            }
            if (net > 1000m)
                tax += net * 0.01m;
        }
        return ApplyRounding(tax);
    }

    internal decimal ResolveRate(string countryCode)
    {
        if (string.IsNullOrEmpty(countryCode))
            return _fallbackRate;
        if (_ratesByCountry.TryGetValue(countryCode, out var rate))
            return rate;
        return _fallbackRate;
    }

    internal decimal ApplyRounding(decimal value)
    {
        if (value < 0m)
            return 0m;
        return Math.Round(value, 2, MidpointRounding.AwayFromZero);
    }

    internal decimal EstimateDuty(Order order, Customer customer)
    {
        decimal duty = 0m;
        var rate = ResolveRate(customer.Address.CountryCode);
        foreach (var line in order.Lines)
        {
            if (line.UnitPrice * line.Quantity > 250m)
                duty += line.UnitPrice * line.Quantity * rate * 0.5m;
            else if (line.Quantity > 20)
                duty += line.UnitPrice * line.Quantity * 0.02m;
        }
        if (customer.Tier == CustomerTier.Wholesale)
            duty *= 0.8m;
        return ApplyRounding(duty);
    }
}

internal sealed class OrderDispatchComponent
{
    private readonly IShipper _shipper;
    private readonly HashSet<string> _blockedCountries;
    private readonly List<string> _dispatched = new();

    internal OrderDispatchComponent(IShipper shipper, HashSet<string> blockedCountries)
    {
        _shipper = shipper;
        _blockedCountries = blockedCountries;
    }

    internal string Dispatch(Order order, Customer customer)
    {
        if (_dispatched.Contains(order.Reference))
            return "duplicate";
        if (customer.Tier == CustomerTier.Blocked)
            return "blocked";
        var service = SelectService(customer);
        var label = _shipper.CreateLabel(order.Reference, service);
        _dispatched.Add(order.Reference);
        return label;
    }

    internal string SelectService(Customer customer)
    {
        var basic = customer.Tier switch
        {
            CustomerTier.Wholesale => "freight",
            CustomerTier.Standard => "standard",
            CustomerTier.Blocked => "none",
            _ => "standard",
        };
        if (_blockedCountries.Contains(customer.Address.CountryCode))
            return "none";
        return basic;
    }

    internal IReadOnlyList<string> BuildManifest(Order order)
    {
        var manifest = new List<string>();
        foreach (var line in order.Lines)
        {
            if (line.Quantity > 50)
                manifest.Add($"PALLET {line.Sku}");
            else if (line.Quantity > 0)
                manifest.Add($"PARCEL {line.Sku}");
            else
                manifest.Add($"SKIP {line.Sku}");
        }
        if (manifest.Count == 0)
            manifest.Add("EMPTY");
        return manifest;
    }

    internal int DispatchedCount => _dispatched.Count;
}

internal sealed class OrderCommercialComponent
{
    internal string Classify(Order order, Customer customer)
    {
        if (order.Lines.Count > 20)
            return "bulk";
        if (customer.Tier == CustomerTier.Wholesale && order.Lines.Count > 5)
            return "wholesale-bulk";
        decimal total = 0m;
        foreach (var line in order.Lines)
        {
            total += line.UnitPrice * line.Quantity;
            if (total > 5000m)
                return "high-value";
        }
        if (order.Channel == OrderChannel.Marketplace)
            return "marketplace";
        else if (order.Channel == OrderChannel.Phone)
            return "phone";
        return total > 100m ? "standard" : "small";
    }

    internal decimal ApplyDiscount(Order order, Customer customer)
    {
        decimal subtotal = 0m;
        foreach (var line in order.Lines)
            subtotal += line.UnitPrice * line.Quantity;
        decimal discount = 0m;
        if (customer.Tier == CustomerTier.Wholesale)
            discount = subtotal * 0.1m;
        else if (subtotal > 1000m)
            discount = subtotal * 0.05m;
        if (order.DiscountOverride is { } ovr && ovr > 0m)
            discount = ovr;
        if (order.Channel == OrderChannel.Marketplace && customer.Tier != CustomerTier.Blocked)
            discount += 1m;
        return discount;
    }
}
